    if (node.type === "text") {
      output += node.value;
      continue;
    }
    if (node.type === "value") {
      const value = scalarToString(resolve(node.path, context), node.path, node.location);
      output += node.escaped ? escapeHtml(value) : value;
      continue;
    }

    const value = resolve(node.path, context);
    if (node.type === "if") {
      output += renderNodes(isTruthy(value) ? node.body : node.alternate, context);
      continue;
    }

    if (!Array.isArray(value) || value.length === 0) {
      output += renderNodes(node.alternate, context);
      continue;
    }
    for (let index = 0; index < value.length; index++) {
      output += renderNodes(node.body, {
        root: context.root,
        current: value[index],
        index,
        inEach: true,
      });
    }
  }
  return output;
}
